{"path": "/tmp/sv-178c6470a6694d7b809ef155611e72aa/RecipeCommunity/Services/RecipeService.cs", "file_text": "using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F\n2. Roll out dough on floured surface\n3. Spread crushed tomatoes evenly\n4. Tear mozzarella and distribute\n5. Bake 10-12 minutes until crust is golden\n6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted water until al dente\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino", AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté onion, garlic, and ginger\n4. Add spices, then crushed tomatoes\n5. Simmer 15 minutes, add cream\n6. Add chicken pieces and simmer 10 more minutes", AverageRating = 4.7, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs", Steps = "1. Soak rice noodles in warm water 30 minutes\n2. Make sauce: tamarind, fish sauce, sugar\n3. Stir-fry tofu until golden\n4. Scramble eggs in wok\n5. Add noodles and sauce, toss until coated\n6. Top with sprouts, peanuts, and lime", AverageRating = 4.3, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water, simmer\n3. Warm tortillas in a dry pan\n4. Assemble tacos with beef and toppings\n5. Serve with salsa and sour cream", AverageRating = 4.2, RatingCount = 18 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Dice onion, tomato, jalapeño, and cilantro\n4. Mix everything together\n5. Add lime juice, garlic, and salt to taste\n6. Serve immediately with chips", AverageRating = 4.6, RatingCount = 25 },
            new() { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter and sugars until fluffy\n2. Beat in eggs and vanilla\n3. Mix flour, baking soda, and salt\n4. Combine wet and dry ingredients\n5. Fold in chocolate chips\n6. Bake at 375°F for 9-11 minutes", AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 8, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock\nMiso paste\nTofu\nWakame seaweed\nGreen onions", Steps = "1. Heat dashi stock until simmering\n2. Cut tofu into small cubes\n3. Rehydrate wakame in water\n4. Remove dashi from heat\n5. Whisk in miso paste (do not boil)\n6. Add tofu and wakame, garnish with green onions", AverageRating = 4.4, RatingCount = 10 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.RatingCount = allRatings.Count;
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
"}

