@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star-btn @(star <= HoverRating ? "text-warning" : (star <= CurrentRating ? "text-warning" : "text-muted"))"
              style="font-size: 1.5rem; cursor: pointer;"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              @onclick="() => Rate(star)">★</span>
    }
    @if (Submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
    <div class="small text-muted mt-1">
        Average: @Recipe?.AverageRating.ToString("0.0") / 5 (@Recipe?.RatingCount ratings)
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }
    private Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void Rate(int stars)
    {
        CurrentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetRecipeById(RecipeId);
        Submitted = true;
    }
}

