@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<div class="container">
    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Success!</strong> Your recipe "@Submission.Title" has been submitted.
            <a href="/submit" @onclick="ResetForm" @onclick:preventDefault>Submit another</a>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in Categories)
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients"
                    placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced..." />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Submission.Steps"
                    placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
            </div>

            <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private IReadOnlyList<string> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))
            return;

        RecipeService.SubmitRecipe(Submission);
        SubmitSuccess = true;
    }

    private void ResetForm()
    {
        Submission = new RecipeSubmission();
        SubmitSuccess = false;
    }
}
